const money=(n:number|null,precise=false)=>n===null||!Number.isFinite(n)?'Unavailable':new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:precise?2:0,minimumFractionDigits:precise?2:0}).format(n);
const count=(n:number|null)=>n===null||!Number.isFinite(n)?'Unavailable':new Intl.NumberFormat('en-GB',{maximumFractionDigits:0}).format(n);
const pct=(n:number|null)=>n===null||!Number.isFinite(n)?'Unavailable':(n*100).toFixed(2)+'%';
const mult=(n:number|null)=>n===null||!Number.isFinite(n)?'Unavailable':n.toFixed(2)+'×';
const div=(n:number|null,d:number|null)=>n!==null&&d!==null&&Number.isFinite(n)&&Number.isFinite(d)&&d>0?n/d:null;
